func NewClient(cfg *config.AuthConfig, opts ...client.ClientOption) (*Client, error) {
	if cfg == nil {
		return nil, fmt.Errorf("auth config is required")
	}
	if err := cfg.Validate(); err != nil {
		return nil, fmt.Errorf("invalid auth config: %w", err)
	}

	transport, err := client.NewTransport(cfg, opts...)
	if err != nil {
		return nil, fmt.Errorf("creating transport: %w", err)
	}

	return &Client{
		Transport: transport,
		API:       newAPI(transport),
	}, nil
}

// NewClientFromEnv returns a client configured from the environment, reading
// TE_TOKEN, TE_AID and TE_API_ENDPOINT.
func NewClientFromEnv(opts ...client.ClientOption) (*Client, error) {
	return NewClient(config.AuthConfigFromEnv(), opts...)
}

